resources.string:
"<!DOCTYPE html PUBLIC \"-//W3C//DTD XHTML 1.0 Strict//EN\" \"http://www.w3.org/TR/xhtml1/DTD/xhtml1-strict.dtd\">
<html xmlns=\"http://www.w3.org/1999/xhtml\">
<head>
	<meta http-equiv=\"Content-Type\" content=\"text/html; charset=UTF-8\" />
	<meta name=\"viewport\" content=\"initial-scale=1.0, minimum-scale=0.02, maximum-scale=5.0\" />
	<title></title>
	<style type=\"text/css\">
html, body { height:100\%%; padding:0; margin:0; }
div#table { height:100\%%; width:100\%%; display:table; }
div#cell { display:table-cell; vertical-align:middle; text-align:center;}
div#maps { width:{{sizex}}px; height:{{sizey}}px; position:relative; display:inline-block; }
div#playerPosition { position:absolute; z-index:3; font-size:19pt; color:red; text-shadow:rgba(0, 0, 0, 1) 2px 2px 2px; }
img { z-index:1; position:absolute; }
img[data-src] { visibility:hidden; }
html.positioning body { visibility:hidden; }
.namedarea { position: absolute; z-index:2; font-size:16pt; text-shadow:black 0.1em 0.1em 0.2em; text-align:center; }
.namedarea span { display:inline-block; vertical-align:middle; line-height:1em; }
.settlement { color:white; }
.other { color:#cccccc; }
	</style>
	<script type=\"text/javascript\">
	// Keeps the page hidden until the script at the end of the body has scrolled to the player and the
	// images around it are ready, so that neither the top left corner nor empty frames are ever shown.
	// If that script does not run, DisplayWorldMapActivity removes this class when the page has loaded.
	document.documentElement.className = \"positioning\";
	</script>
</head>
<body>

<div id=\"table\">
<div id=\"cell\">
<div id=\"maps\">
{{maps}}
{{areas}}
<div id=\"playerPosition\">x</div>
</div>
</div>
</div>

<script type=\"text/javascript\">
var player = document.getElementById(\"playerPosition\");
var params = window.location.search.substring(1);
var playerX = null;
var playerY = null;
if (params) {
	var pos = params.split(\",\");
	playerX = parseInt(pos[0])-({{offsetx}});
	playerY = parseInt(pos[1])-({{offsety}});
	player.style.top = playerY + \"px\";
	player.style.left = playerX + \"px\";
} else {
	player.style.display = \"none\";
}

// A world map segment can contain hundreds of map images. Loading all of them makes the
// map slow to open, so the images only get their src when they come close to the screen.
(function() {
	var maps = document.getElementById(\"maps\");
	var images = maps.getElementsByTagName(\"img\");
	var pending = [];
	var loadScheduled = false;

	function show() {
		document.documentElement.className = \"\";
	}

	function loadImage(image) {
		image.setAttribute(\"src\", image.getAttribute(\"data-src\"));
		image.removeAttribute(\"data-src\");
	}

	for (var i = 0; i < images.length; ++i) {
		var image = images[i];
		if (!image.getAttribute(\"data-src\")) continue;
		var left = parseInt(image.style.left, 10);
		var top = parseInt(image.style.top, 10);
		var width = parseInt(image.style.width, 10);
		var height = parseInt(image.style.height, 10);
		if (isNaN(left) || isNaN(top) || isNaN(width) || isNaN(height)) {
			loadImage(image);
			continue;
		}
		pending.push({ image: image, left: left, top: top, right: left + width, bottom: top + height });
	}

	function overlaps(p, area) {
		return p.right >= area.left && p.bottom >= area.top && p.left <= area.right && p.top <= area.bottom;
	}

	// Loads the images that overlap the given area, and returns the ones among them that overlap
	// the visible area. Coordinates are relative to the maps element.
	function loadImagesInArea(area, visibleArea) {
		var remaining = [];
		var visible = [];
		for (var i = 0; i < pending.length; ++i) {
			var p = pending[i];
			if (overlaps(p, area)) {
				loadImage(p.image);
				if (overlaps(p, visibleArea)) visible.push(p.image);
			} else {
				remaining.push(p);
			}
		}
		pending = remaining;
		return visible;
	}

	// What is shown on screen is the visual viewport. The layout viewport of this page is
	// enlarged to fit the minimum zoom level and covers most of the map, so IntersectionObserver
	// and loading=lazy, which are based on the layout viewport, would still load almost everything.
	function getVisibleArea() {
		var viewport = window.visualViewport;
		var x, y, width, height;
		if (viewport) {
			x = viewport.pageLeft;
			y = viewport.pageTop;
			width = viewport.width;
			height = viewport.height;
		} else {
			x = window.pageXOffset;
			y = window.pageYOffset;
			width = window.innerWidth;
			height = window.innerHeight;
		}
		var origin = maps.getBoundingClientRect();
		x -= origin.left + window.pageXOffset;
		y -= origin.top + window.pageYOffset;
		return { left: x, top: y, right: x + width, bottom: y + height };
	}

	// Loads the visible images and half a screen around them, so that images are ready when scrolling.
	function loadVisibleImages() {
		loadScheduled = false;
		var visibleArea = getVisibleArea();
		var margin = Math.max(visibleArea.right - visibleArea.left, visibleArea.bottom - visibleArea.top) / 2;
		var area = { left: visibleArea.left - margin, top: visibleArea.top - margin, right: visibleArea.right + margin, bottom: visibleArea.bottom + margin };
		return loadImagesInArea(area, visibleArea);
	}

	function scheduleLoad() {
		if (loadScheduled || pending.length == 0) return;
		loadScheduled = true;
		window.setTimeout(loadVisibleImages, 50);
	}

	// Scrolls the page so that the player marker is in the middle of the screen. The layout is final
	// at this point: the page and every image have a fixed size and position. window.scrollTo cannot be
	// used, because it only moves the enlarged layout viewport and not what is shown on screen.
	// scrollIntoView with options is available from Chromium 61, older WebViews let the activity scroll.
	function scrollToPlayer() {
		if (!(\"scrollBehavior\" in document.documentElement.style)) return false;
		player.scrollIntoView({ block: \"center\", inline: \"center\" });
		return true;
	}

	// Shows the page once the given images are loaded and decoded, so that the first screen
	// is complete when it appears. Later images appear when they are ready.
	function showWhenReady(visibleImages) {
		var remaining = visibleImages.length;
		function imageReady() {
			if (--remaining == 0) show();
		}
		if (remaining == 0) {
			show();
			return;
		}
		for (var i = 0; i < visibleImages.length; ++i) {
			var image = visibleImages[i];
			if (image.decode) {
				image.decode().then(imageReady, imageReady);
			} else if (image.complete) {
				imageReady();
			} else {
				image.addEventListener(\"load\", imageReady, false);
				image.addEventListener(\"error\", imageReady, false);
			}
		}
	}

	window.addEventListener(\"scroll\", scheduleLoad, false);
	window.addEventListener(\"resize\", scheduleLoad, false);
	if (window.visualViewport) {
		window.visualViewport.addEventListener(\"scroll\", scheduleLoad, false);
		window.visualViewport.addEventListener(\"resize\", scheduleLoad, false);
	}
	// Called by DisplayWorldMapActivity after it has scrolled, for example with the recenter button.
	window.startWorldMapLazyLoading = scheduleLoad;

	var hasPlayer = playerX !== null && playerY !== null && !isNaN(playerX) && !isNaN(playerY);
	if (hasPlayer && scrollToPlayer()) {
		// Tells DisplayWorldMapActivity that it does not need to scroll to the player itself.
		window.worldMapCenteredOnPlayer = true;
		// The load event waits for every image that has a src, so the page is shown at the latest then.
		window.addEventListener(\"load\", show, false);
		showWhenReady(loadVisibleImages());
	} else if (hasPlayer) {
		// DisplayWorldMapActivity scrolls to the player when the page has loaded, and then shows it.
		// Load the area around the player now, so that it is ready at that point.
		var screenSize = window.visualViewport ? Math.max(window.visualViewport.width, window.visualViewport.height) : 1024;
		var aroundPlayer = { left: playerX - screenSize, top: playerY - screenSize, right: playerX + screenSize, bottom: playerY + screenSize };
		loadImagesInArea(aroundPlayer, aroundPlayer);
	} else {
		show();
		scheduleLoad();
	}
})();
</script>

</body>
</html>
